        public void Open(){reader.gameObject.SetActive(true);revision=-1;Refresh();}
        public void Close(){if(reader!=null)reader.gameObject.SetActive(false);}
        void Read()=>owner.Open(owner.session.stations[9]);
        void Submit(){if(ArchiveTreePresentation.ReadyToCheck(owner.session.Question(9),owner.session.State.stations[9]))owner.session.Request(9,ArchiveAction.Submit);}
        void Primary(){var s=owner.session.State.stations[9];if(s.phase==0)owner.session.Request(9,ArchiveAction.Start);else if(s.phase==1)Submit();else owner.Close();}
        void Edit(bool removing){var actor=owner.session.TreeSelection(owner.session.LocalActor);if(actor!=null)owner.session.Request(9,removing?ArchiveAction.Remove:ArchiveAction.Connect,actor.treeFirst,actor.treeSecond);}
